export function lookupStaticAsset(inputUrl?: string | null): string | null {
  if (!inputUrl || typeof inputUrl !== 'string') return null;
  const trimmed = inputUrl.trim();
  if (!trimmed || trimmed.startsWith('data:') || trimmed.startsWith('blob:') || trimmed.startsWith('http://') || trimmed.startsWith('https://')) {
    return null;
  }
  
  // Clean query strings and normalize slashes
  const clean = trimmed.split('?')[0].replace(/\\/g, '/');
  const baseName = clean.split('/').pop() || '';
  const baseNameLower = baseName.toLowerCase();
  const cleanLower = clean.toLowerCase();
  
  // 1. Direct path match
  if (STATIC_ASSET_MAP[clean]) return STATIC_ASSET_MAP[clean];
  if (STATIC_ASSET_MAP[cleanLower]) return STATIC_ASSET_MAP[cleanLower];
  
  // 2. Add or remove leading slash
  const withSlash = clean.startsWith('/') ? clean : '/' + clean;
  if (STATIC_ASSET_MAP[withSlash]) return STATIC_ASSET_MAP[withSlash];
  if (STATIC_ASSET_MAP[withSlash.toLowerCase()]) return STATIC_ASSET_MAP[withSlash.toLowerCase()];
  
  // 3. Match by basename (e.g. time_to_travel.png -> /templates/data/time_to_travel.png)
  if (baseName && STATIC_ASSET_MAP[baseName]) return STATIC_ASSET_MAP[baseName];
  if (baseNameLower && STATIC_ASSET_MAP[baseNameLower]) return STATIC_ASSET_MAP[baseNameLower];
  
  return null;
}
